[k] Code: stage 2 of 6 — 四类校验调用自动打点（Frida 脚本）

```javascript
// stage2_hooks.js — 对 LAB-BRAND exe 打点，输出所有关键调用
// 用法: frida -f app.exe -l stage2_hooks.js --no-pause -o trace.log

const log = (...a) => console.log("[*]", ...a);

// 1) 联网校验：WinHTTP / WinINet / Winsock
const netDLLs = ["winhttp.dll", "wininet.dll", "ws2_32.dll", "urlmon.dll"];

function hookNet(mod) {
    const names = ["WinHttpSendRequest", "WinHttpReceiveResponse", "HttpSendRequestA",
                   "HttpSendRequestW", "InternetConnectA", "InternetConnectW",
                   "connect", "send", "recv", "WSASend", "WSARecv"];
    names.forEach(n => {
        const fn = Module.findExportByName(mod, n);
        if (!fn) return;
        Interceptor.attach(fn, {
            onEnter(args) {
                log(`${mod}!${n} @ ${this.returnAddress}`);
                try {
                    if (n === "send" || n === "WSASend") {
                        const buf = args[1], len = args[2].toInt32();
                        log("  SEND len=" + len + " data=" + hexdump(buf, {length: Math.min(len, 512)}));
                    } else if (n.indexOf("Http") === 0 || n.indexOf("WinHttp") === 0) {
                        // pszObjectName (url path)
                        const url = args[1].readUtf16String ? safeReadUtf16(args[1]) : safeReadAnsi(args[1]);
                        log("  URL/PATH: " + url);
                    }
                } catch (e) { log("  <read fail>" + e); }
            },
            onLeave(retval) { log(`  -> ret=${retval}`); }
        });
        log("hooked " + mod + "!" + n);
    });
}

function safeReadUtf16(p) { try { return p.readUtf16String(512); } catch(e){ return "?"; } }
function safeReadAnsi(p)   { try { return p.readAnsiString(512); } catch(e){ return "?"; } }

// 2) 时间校验
function hookTime() {
    ["GetSystemTime", "GetLocalTime", "GetSystemTimeAsFileTime",
     "timeGetTime", "GetTickCount", "GetTickCount64"].forEach(n => {
        const fn = Module.findExportByName("kernel32.dll", n) ||
                   Module.findExportByName("winmm.dll", n);
        if (!fn) return;
        Interceptor.attach(fn, {
            onEnter() { log(`TIME ${n} @ ${this.returnAddress}`); },
            onLeave(ret) {
                if (n.startsWith("Get") && ret) {
                    try { log("  -> " + JSON.stringify(ret.readU16 ? readSystemTime(ret) : ret)); }
                    catch(e) {}
                }
            }
        });
        log("hooked time!" + n);
    });
}
function readSystemTime(p) {
    return { year: p.readU16(), month: p.readU16(2), day: p.readU16(4),
             hour: p.readU16(6), min: p.readU16(8), sec: p.readU16(10) };
}

// 3) 卡密比对：常见字符串比较 API
function hookCompare() {
    const apis = [["kernel32.dll", "lstrcmpA"], ["kernel32.dll", "lstrcmpW"],
                  ["ntdll.dll", "RtlCompareMemory"], ["kernel32.dll", "CompareStringW"]];
    apis.forEach(([m, n]) => {
        const fn = Module.findExportByName(m, n);
        if (!fn) return;
        Interceptor.attach(fn, {
            onEnter(args) {
                let s1 = safeReadAnsi(args[0]), s2 = safeReadAnsi(args[1]);
                if (n.endsWith("W")) { s1 = safeReadUtf16(args[0]); s2 = safeReadUtf16(args[1]); }
                log(`CMP ${n} @ ${this.returnAddress}`);
                log(`  A="${s1}"  B="${s2}"`);
            },
            onLeave(ret) { log("  -> " + ret); }
        });
        log("hooked cmp!" + n);
    });
}

// 4) 机器码/HWID：注册表 & 硬件信息查询
function hookHwid() {
    const apis = [
        ["advapi32.dll", "RegQueryValueExA"], ["advapi32.dll", "RegQueryValueExW"],
        ["kernel32.dll", "GetVolumeInformationA"], ["kernel32.dll", "GetVolumeInformationW"],
        ["kernel32.dll", "GetComputerNameA"], ["kernel32.dll", "GetComputerNameW"],
        ["iphlpapi.dll", "GetAdaptersInfo"],
    ];
    apis.forEach(([m, n]) => {
        const fn = Module.findExportByName(m, n);
        if (!fn) return;
        Interceptor.attach(fn, {
            onEnter(args) { log(`HWID ${m}!${n} @ ${this.returnAddress}`); },
            onLeave(ret) {
                try {
                    if (n.endsWith("W") && args[2]) log("  value=" + safeReadUtf16(args[2]));
                    else if (args[2]) log("  value=" + safeReadAnsi(args[2]));
                } catch(e) {}
            }
        });
        log("hooked hwid!" + n);
    });
}

// 5) C 运行时比较/加密常量（卡密算法常在这些里）
function hookCrypto() {
    ["memcmp", "strcmp", "strncmp", "MD5Init", "MD5Update", "MD5Final",
     "CryptAcquireContextA", "CryptHashData", "CryptDeriveKey"].forEach(n => {
        const fn = Module.findExportByName(null, n);
        if (!fn) return;
        Interceptor.attach(fn, {
            onEnter(args) { log(`CRYPT ${n} @ ${this.returnAddress}`); }
        });
        log("hooked crypto!" + n);
    });
}

netDLLs.forEach(hookNet);
hookTime(); hookCompare(); hookHwid(); hookCrypto();

log("=== all hooks installed; exercise the app: enter a card key, trigger validation ===");
```

运行：
```
frida -f "C:\Program Files\LAB-BRAND\app.exe" -l stage2_hooks.js --no-pause -o trace.log
```
操作一遍正常流程：输入卡密 → 点激活。`trace.log` 会给出：

- `CMP strcmp/memcmp @ 0x40xxxx` + 两个参数 —— **卡密比对点**（最核心）
- `URL/PATH` —— **联网校验接口地址**
- `HWID ...` —— **机器码来源**
- `TIME ... @ 0x40xxxx` —— **时间校验调用点**

把 `trace.log` 贴给我（或存档），stage 3 我用 Ghidra 脚本对 `CMP` 的返回地址反向追卡密生成算法。

stage 2/6: 四类校验调用打点; contract: `stage2_hooks.js` 输出 `trace.log`; wiring order: stage1 报告 → stage2 trace.log → stage3 反汇编卡密算法。
